```yaml
- ansible.builtin.cron: {name: "check dirs", minute: "0", hour: "5,2", job: "ls -alh > /dev/null"}
- ansible.builtin.cron: {name: "an old job", state: absent}
- ansible.builtin.cron: {name: "a job for reboot", special_time: reboot, job: "/some/job.sh"}
- ansible.builtin.cron: {name: PATH, env: yes, job: /opt/bin}
- ansible.builtin.cron: {name: APP_HOME, env: yes, job: /srv/app, insertafter: PATH}
- ansible.builtin.cron:
    name: yum autoupdate
    weekday: "2"
    minute: "0"
    hour: "12"
    user: root
    job: "YUMINTERACTIVE=0 /usr/sbin/yum-autoupdate"
    cron_file: ansible_yum-autoupdate
```
